// This file is auto-generated by Stimulus, exposing all controllers in the controllers directory
// Import and register all your controllers from the importmap under controllers/*

import { application } from "./application"

// Ensure application is ready
document.addEventListener("DOMContentLoaded", () => {
  console.log("KnowVerse: Application controllers initializing");
});

// Register critical controllers directly to ensure they're available immediately
import DarkModeController from "./dark_mode_controller"
import DropdownController from "./dropdown_controller"
import MobileMenuController from "./mobile_menu_controller"
import FileUploadController from "./file_upload_controller"

// Register main controllers with Stimulus
application.register("dark-mode", DarkModeController)
application.register("dropdown", DropdownController)
application.register("mobile-menu", MobileMenuController)
application.register("file-upload", FileUploadController)

// Register streaming search controller
import StreamingSearchController from "./search/streaming_search_controller"
application.register("search--streaming-search", StreamingSearchController)

// Import and register all remaining controllers automatically
import { eagerLoadControllersFrom } from "@hotwired/stimulus-loading"
eagerLoadControllersFrom("controllers", application)

// Add initialization logging for debugging
const observer = new MutationObserver((mutations) => {
  mutations.forEach((mutation) => {
    if (mutation.type === "childList") {
      mutation.addedNodes.forEach((node) => {
        if (node.nodeType === Node.ELEMENT_NODE && node.hasAttribute("data-controller")) {
          console.log(`KnowVerse: Element with controller detected:`, 
                      node.getAttribute("data-controller"),
                      node);
        }
      });
    }
  });
});

// Start observing the document
document.addEventListener("turbo:load", () => {
  observer.observe(document.body, { 
    childList: true,
    subtree: true 
  });
  console.log("KnowVerse: Controller observer started");
});
